import {createRegion,seedDistrict,analyze,deserialize,serialize} from './engine.mjs';
import {PRESETS,makeTerrain,nextTerrainSeed,regionLabel} from './terrain.mjs';
import {terrainSurvey} from './terrain-style.mjs';
import {drawTerrainPreview} from './terrain-preview.mjs';
import {importTerrain} from './terrain-import.mjs';
export function setupOpening({getCity,savedCity,suspend,preview,start,onImportData,kepler}){
 const el=document.createElement('section');el.id='opening';el.setAttribute('aria-label','Sim City 2020 welcome');el.innerHTML=`<div class="opening-shade"></div><div id="welcome-screen"><svg class="city-logo" viewBox="0 0 100 90" aria-hidden="true"><path d="M8 82V47l18-10v45M34 82V22L54 9v73M62 82V36l25-15v61M8 82h79"/><path d="M42 31v40M70 41v30M16 53v18"/></svg><p class="eyebrow">A WORLD OF YOUR OWN MAKING</p><h1>SIM CITY <em>2020</em></h1><p>Shape the land. Build the future.</p><button id="start-new" class="primary">Start a city <span>→</span></button><button id="continue-city" ${savedCity?'':'hidden'}>Continue saved city</button><button id="opening-import">Import city save</button><small>Three.js · deck.gl · kepler.gl · v0.5.1</small></div>
 <div id="map-selection" hidden><div class="selection-heading"><div><p class="eyebrow">THE REGIONAL ATLAS / 12 LANDSCAPES</p><h2>Every city begins with the land.</h2><p>January 1900 · 0 residents · 8 minutes per year at 1×</p></div><button id="selection-back">← Back</button></div>
 <div class="region-browser"><div class="region-library"><div class="atlas-label">CHOOSE A LANDSCAPE <span>12 / 12</span></div><div class="map-grid" id="preset-grid" aria-label="Preloaded regions"></div></div>
 <div class="region-detail"><div class="survey-header"><div><h3 id="region-name"></h3><span id="region-size"></span></div><div class="survey-tabs" role="group" aria-label="Terrain preview mode"><button data-survey="relief" aria-pressed="true">Relief</button><button data-survey="contours" aria-pressed="false">Contours</button><button data-survey="suitability" aria-pressed="false">Buildable</button></div></div>
 <div class="terrain-preview-wrap"><canvas id="terrain-preview" width="900" height="490" role="img" aria-label="Selected region terrain survey"></canvas><div id="survey-legend" class="survey-legend"></div></div>
 <div id="terrain-metrics" class="terrain-metrics"></div><p id="region-description"></p>
 <div class="terrain-tuning"><label>Relief <output id="relief-value">100%</output><input id="terrain-relief" type="range" min="40" max="180" value="100"></label><label>Water <output id="water-value">100%</output><input id="terrain-water" type="range" min="50" max="150" value="100"></label><label>Forest <output id="forest-value">100%</output><input id="terrain-forest" type="range" min="0" max="180" value="100"></label></div>
 <div class="seed-controls"><label for="terrain-seed">SEED</label><input id="terrain-seed" type="number" min="1" max="2147483647" value="2020"><button id="apply-terrain-seed">Apply seed</button><button id="regenerate-region">↻ Regenerate</button></div>
 <div class="atlas-footer"><label class="policy"><input id="starter-district" type="checkbox">Starter roads, utilities & zoning <small>Preview includes the prepared site</small></label><button id="build-region" class="primary">Build here →</button></div><p id="terrain-status" role="status" aria-live="polite"></p>
 </div></div>
 <details class="terrain-import-details"><summary>Import your own terrain</summary><label class="upload-terrain">CSV / GeoJSON <input id="terrain-upload" type="file" accept=".csv,.geojson,.json"></label><p class="import-guide">Kepler terrain import: CSV x,y,elevation_m,water or longitude,latitude,elevation_m. GeoJSON: elevation points + water polygons. <a href="samples/terrain.csv" download>Sample CSV</a></p></details></div>`;
 document.body.append(el);document.body.classList.add('opening');
 const $=id=>document.getElementById(id);let selected='estuary',custom=null,fromGame=false,returnCity=null,mode='relief',base=null,busy=false,cardsReady=false;
 for(const spec of PRESETS){const button=document.createElement('button');button.className='region-card';button.dataset.preset=spec.id;button.setAttribute('aria-label',spec.name);button.innerHTML=`<canvas width="280" height="156" role="img" aria-label="${spec.name} preview"></canvas><span class="region-card-text"><strong>${spec.name}</strong><small>${spec.tag}</small></span>`;button.onclick=()=>choose(spec.id);$('preset-grid').append(button);}
 function config(){return Object.fromEntries(['relief','water','forest'].map(k=>[k,+$('terrain-'+k).value/100]));}
 function paint(){const canvas=$('terrain-preview'),rect=canvas.getBoundingClientRect();canvas.width=Math.max(400,Math.round(rect.width));canvas.height=Math.max(200,Math.round(rect.height));const c=getCity(),s=drawTerrainPreview(canvas,c,{mode});$('terrain-metrics').innerHTML=`<div><strong>${s.waterPercent.toFixed(0)}<small>%</small></strong><span>Water</span></div><div><strong>${s.gentlePercent.toFixed(0)}<small>%</small></strong><span>Gentle land¹</span></div><div><strong>${s.forestPercent.toFixed(0)}<small>%</small></strong><span>Woodland</span></div><div><strong>${Math.round(s.maxElevation).toLocaleString()}<small>m</small></strong><span>Highest point</span></div>`;
 $('survey-legend').innerHTML=mode==='suitability'?'<span><i style="background:#84a760"></i>0–12% grade</span><span><i style="background:#bea65f"></i>12–30%</span><span><i style="background:#9b6f5e"></i>&gt;30%</span>':mode==='contours'?'<span><i style="background:#9aa372"></i>Elevation contours</span><span><i style="background:#366f85"></i>Water</span>':'<span><i style="background:#366f85"></i>Water</span><span><i style="background:#8c9860"></i>Meadow</span><span><i style="background:#445b32"></i>Forest</span><span><i style="background:#9c9988"></i>Rock</span>';
 $('terrain-preview').setAttribute('aria-label',`${c.name}: ${s.waterPercent.toFixed(0)} percent water, ${s.gentlePercent.toFixed(0)} percent gentle land, maximum elevation ${Math.round(s.maxElevation)} metres. Seed ${c.seed}.`);
 }
 function describe(){const c=getCity(),spec=PRESETS.find(s=>s.id===selected);$('region-name').textContent=c.name;$('region-description').textContent=(custom?'Your uploaded elevations and water mask.':spec.description)+' ¹ Gentle land is terrain under 12% grade, not a guarantee of service access.';$('region-size').textContent=regionLabel(c)+' · '+c.tiles.length.toLocaleString()+' parcels';for(const id of ['terrain-seed','regenerate-region','apply-terrain-seed','terrain-relief','terrain-water','terrain-forest'])$(id).disabled=!!custom;
 document.querySelectorAll('.region-card').forEach(b=>{b.classList.toggle('selected',b.dataset.preset===selected);b.setAttribute('aria-pressed',String(b.dataset.preset===selected));});paint();
 const card=document.querySelector(`.region-card[data-preset="${selected}"] canvas`);if(card)drawTerrainPreview(card,c,{detail:false});
 }
 function applyPreview(){const c=deserialize(serialize(base));if($('starter-district').checked){seedDistrict(c);analyze(c);}preview(c);describe();}
 function generate(seed){base=createRegion(selected,{starter:false,seed,terrainConfig:config()});$('terrain-seed').value=seed;applyPreview();}
 function choose(id){if(busy)return;custom=null;selected=id;const spec=PRESETS.find(p=>p.id===id);generate(nextTerrainSeed(getCity().seed));$('terrain-status').textContent='A random seed was generated automatically. Regenerate explores another map; Apply seed reproduces one.';}
 async function prepareCards(){if(cardsReady)return;cardsReady=true;for(const spec of PRESETS){await new Promise(r=>setTimeout(r,0));if(spec.id===selected)continue;const c=makeTerrain(spec.id,{width:96,height:72,cellSize:16384/96});drawTerrainPreview(document.querySelector(`.region-card[data-preset="${spec.id}"] canvas`),c,{detail:false});}}
 function openMaps(){returnCity=getCity();suspend();fromGame=!document.body.classList.contains('opening');el.hidden=false;document.body.classList.add('opening');$('welcome-screen').hidden=true;$('map-selection').hidden=false;choose(PRESETS.some(p=>p.id===selected)?selected:'estuary');prepareCards();}
 function hide(){el.hidden=true;document.body.classList.remove('opening');}
 async function perform(fn,message){if(busy)return;busy=true;$('build-region').disabled=true;$('terrain-status').textContent='Generating terrain…';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));try{fn();$('terrain-status').textContent=message+` Seed ${getCity().seed}.`;}catch(error){$('terrain-status').textContent=error.message;}finally{busy=false;$('build-region').disabled=false;}}
 function applySeed(){const seed=+$('terrain-seed').value;if(!Number.isInteger(seed)||seed<1||seed>2147483647){$('terrain-status').textContent='Choose an integer seed between 1 and 2,147,483,647.';return;}perform(()=>generate(seed),'Reproduced from your seed and terrain settings.');}
 $('start-new').onclick=openMaps;$('continue-city').onclick=()=>{hide();start(savedCity);};$('opening-import').onclick=()=>document.getElementById('import-file').click();
 $('selection-back').onclick=()=>{if(busy)return;if(fromGame&&returnCity){hide();start(returnCity);return;}$('map-selection').hidden=true;$('welcome-screen').hidden=false;};
 $('regenerate-region').onclick=()=>perform(()=>generate(nextTerrainSeed(getCity().seed)),'New landscape ready.');$('apply-terrain-seed').onclick=applySeed;$('terrain-seed').onkeydown=e=>{if(e.key==='Enter')applySeed();};
 for(const key of ['relief','water','forest']){$('terrain-'+key).oninput=()=>{$(key+'-value').textContent=$('terrain-'+key).value+'%';};$('terrain-'+key).onchange=()=>perform(()=>generate(getCity().seed),'Terrain settings applied.');}
 $('starter-district').onchange=()=>perform(applyPreview,'Prepared site updated in the preview.');
 for(const b of el.querySelectorAll('[data-survey]'))b.onclick=()=>{mode=b.dataset.survey;el.querySelectorAll('[data-survey]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paint();};
 // Build the exact object already previewed. Never seed or flatten again on Start.
 $('build-region').onclick=()=>{if(busy)return;const c=getCity();hide();start(c);};
 $('terrain-upload').onchange=async event=>{const f=event.target.files[0];if(!f||busy)return;busy=true;const status=$('terrain-status');$('build-region').disabled=true;try{if(f.size>25e6)throw Error('Use a terrain file under 25 MB.');status.textContent='Reading terrain…';await new Promise(r=>requestAnimationFrame(r));const text=await f.text(),json=!f.name.toLowerCase().endsWith('.csv'),raw=json?JSON.parse(text):null,processed=json?kepler.processGeojson(raw):kepler.processCsvData(text);if(!processed?.fields)throw Error('Kepler could not read this dataset.');const imported=importTerrain(json?raw:processed,{name:f.name.replace(/\.[^.]+$/,'')});custom=imported;selected='imported';base=imported;onImportData(processed,f.name);$('starter-district').checked=false;applyPreview();status.textContent='Terrain imported. Preview and game use these same elevations.';}catch(error){status.textContent=error.message;}finally{event.target.value='';busy=false;$('build-region').disabled=false;}};
 let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!$('map-selection').hidden&&base)paint();},120);});
 return {openMaps,hide};
}
